package cl.bolsillo.app;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.util.*;

public class BolsilloWidget extends AppWidgetProvider {
 static final String REFRESH="cl.bolsillo.REFRESH_WIDGET";
 static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,BolsilloWidget.class)))render(c,m,id);}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)render(c,m,id);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle options){render(c,m,id);}
 @Override public void onDeleted(Context c,int[] ids){for(int id:ids)WidgetPreferences.remove(c,id);}
 @Override public void onRestored(Context c,int[] oldIds,int[] newIds){for(int i=0;i<Math.min(oldIds.length,newIds.length);i++)try{WidgetPreferences.write(c,newIds[i],WidgetPreferences.read(c,oldIds[i]));if(oldIds[i]!=newIds[i])WidgetPreferences.remove(c,oldIds[i]);}catch(Exception ignored){}updateAll(c);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(REFRESH.equals(i.getAction())){int id=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(id!=AppWidgetManager.INVALID_APPWIDGET_ID&&!WidgetPreferences.belongs(c,id))return;PendingResult pending=goAsync();NativeSync.run(c,(ok,message)->{try{if(id==AppWidgetManager.INVALID_APPWIDGET_ID)updateAll(c);else render(c,AppWidgetManager.getInstance(c),id);}finally{pending.finish();}});}}
 static String money(long n){return java.text.NumberFormat.getCurrencyInstance(new Locale("es","CL")).format(n);}
 static Uri identity(int id,String action){return Uri.parse("bolsillo-widget://"+id+"/"+action);}
 static PendingIntent activity(Context c,int id,String quick){JSONObject preferences=WidgetPreferences.read(c,id);Intent intent=new Intent(c,quick.isEmpty()?MainActivity.class:QuickEntryActivity.class).putExtra("quick",quick).putExtra("quickAccount",preferences.optString("display").equals("account")?preferences.optString("account"):"").setData(identity(id,quick.isEmpty()?"open":quick)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);return PendingIntent.getActivity(c,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent configure(Context c,int id){return PendingIntent.getActivity(c,id,new Intent(c,WidgetConfigActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).setData(identity(id,"configure")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static final class Snapshot {String label,detail;long value,available,savings,updated,income,expense;int queued;boolean missing;}
 static Snapshot snapshot(Context c,JSONObject preferences)throws Exception{
  JSONObject cache=NativeStore.cached(c);if(cache==null)throw new Exception("Abre Bolsillo para cargar tus cuentas");JSONObject data=new JSONObject(cache.getJSONObject("data").toString());JSONArray transactions=data.getJSONArray("transactions"),queue=NativeStore.queue(c);Set<String> ids=new HashSet<>();for(int i=0;i<transactions.length();i++)ids.add(transactions.getJSONObject(i).getString("id"));int queued=0;for(int i=0;i<queue.length();i++){JSONObject e=queue.getJSONObject(i);if(cache.optString("ownerId").equals(e.optString("ownerId"))&&ids.add(e.getJSONObject("tx").getString("id"))){transactions.put(e.getJSONObject("tx"));queued++;}}
  Snapshot result=new Snapshot();result.queued=queued;result.updated=NativeStore.settings(c).getLong("lastSync",0);Map<String,Long> balances=Ledger.balances(data,Ledger.today());JSONArray accounts=data.getJSONArray("accounts");for(int i=0;i<accounts.length();i++){JSONObject account=accounts.getJSONObject(i);if(!account.optBoolean("included")||account.optBoolean("archived"))continue;long value=balances.get(account.getString("id"));result.value=Math.addExact(result.value,value);String type=account.optString("type");if(type.equals("cash")||type.equals("bank"))result.available=Math.addExact(result.available,value);if(type.equals("savings")||type.equals("investment"))result.savings=Math.addExact(result.savings,value);}
  String display=preferences.optString("display","total");result.label="Patrimonio";result.detail="Disponible "+money(result.available)+" · Ahorro "+money(result.savings);
  if(display.equals("available")){result.label="Dinero disponible";result.value=result.available;result.detail="Cuentas y efectivo · saldo local";}else if(display.equals("savings")){result.label="Ahorro e inversión";result.value=result.savings;result.detail="Ahorro registrado en tu teléfono";}else if(display.equals("account")){JSONObject account=Ledger.find(accounts,preferences.optString("account"));if(account==null||account.optBoolean("archived")){result.label="Cuenta no disponible";result.missing=true;result.value=0;result.detail="Toca ajustes y elige otra cuenta";}else{result.label=account.optString("name");result.value=balances.get(account.getString("id"));result.detail="Saldo de tus registros locales";}}
  String month=Ledger.today().substring(0,7);String selected=display.equals("account")?preferences.optString("account"):"";for(int i=0;i<transactions.length();i++){JSONObject tx=transactions.getJSONObject(i);if(!tx.optString("status").equals("posted")||tx.optBoolean("excluded")||!tx.optString("date").startsWith(month)||tx.optString("date").compareTo(Ledger.today())>0||!selected.isEmpty()&&!tx.optString("account").equals(selected))continue;if(tx.optString("type").equals("income"))result.income=Math.addExact(result.income,tx.getLong("amount"));if(tx.optString("type").equals("expense"))result.expense=Math.addExact(result.expense,Finance.personalExpense(tx));}
  return result;
 }
 static Bitmap icon(Context c,String name,int color){Bitmap image=Bitmap.createBitmap(48,48,Bitmap.Config.ARGB_8888);Icons.Line icon=new Icons.Line(c,name,color);icon.setBounds(2,2,46,46);icon.draw(new Canvas(image));return image;}
 static Bitmap flow(WidgetSkin skin,long income,long expense){Bitmap b=Bitmap.createBitmap(420,8,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(WidgetSkin.alpha(skin.subtle,45));canvas.drawRoundRect(0,0,420,8,4,4,p);long total=income+expense;if(total>0){float x=(float)(420d*income/total);p.setColor(skin.accent);canvas.drawRoundRect(0,0,x,8,4,4,p);p.setColor(skin.secondary);canvas.drawRoundRect(Math.min(420,x+3),0,420,8,4,4,p);}return b;}
 static void render(Context c,AppWidgetManager manager,int id){manager.updateAppWidget(id,views(c,id,manager.getAppWidgetOptions(id)));}
 static RemoteViews views(Context c,int id,Bundle dimensions){
  JSONObject options=WidgetPreferences.read(c,id);WidgetSkin skin=new WidgetSkin(c,options);int width=dimensions.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,300),height=dimensions.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,180);String layout=options.optString("layout","auto");boolean compact=layout.equals("compact")||height<(c.getResources().getConfiguration().fontScale>1.2f?255:225);boolean hidden=options.optBoolean("hidden");RemoteViews views=new RemoteViews(c.getPackageName(),compact?R.layout.bolsillo_widget_compact:R.layout.bolsillo_widget);
  views.setImageViewBitmap(R.id.widget_background,skin.surface(Math.max(320,width*2),Math.max(230,height*2),false));views.setImageViewBitmap(R.id.widget_refresh,icon(c,"refresh",skin.accent));views.setImageViewBitmap(R.id.widget_settings,icon(c,"settings",skin.subtle));
  for(int text:new int[]{R.id.widget_title,R.id.widget_balance})views.setTextColor(text,skin.ink);for(int text:new int[]{R.id.widget_label,R.id.widget_detail,R.id.widget_updated,R.id.widget_left_label,R.id.widget_right_label})views.setTextColor(text,skin.subtle);for(int text:new int[]{R.id.widget_expense,R.id.widget_income,R.id.widget_move})views.setTextColor(text,skin.accent);
  views.setTextColor(R.id.widget_left_value,skin.ink);views.setTextColor(R.id.widget_right_value,skin.ink);views.setImageViewBitmap(R.id.widget_expense_icon,icon(c,"expense",skin.accent));views.setImageViewBitmap(R.id.widget_income_icon,icon(c,"income",skin.accent));views.setImageViewBitmap(R.id.widget_move_icon,icon(c,"transfer",skin.accent));
  Bitmap button=skin.surface(280,100,true);for(int image:new int[]{R.id.widget_expense_bg,R.id.widget_income_bg,R.id.widget_move_bg})views.setImageViewBitmap(image,button);
  views.setViewVisibility(R.id.widget_detail,View.GONE);views.setViewVisibility(R.id.widget_stats,compact?View.GONE:View.VISIBLE);views.setViewVisibility(R.id.widget_updated,height<185?View.GONE:View.VISIBLE);views.setViewVisibility(R.id.widget_actions,options.optBoolean("actions",true)?View.VISIBLE:View.GONE);views.setViewPadding(R.id.widget_content,Glass.dp(c,compact?14:18),Glass.dp(c,compact?8:12),Glass.dp(c,compact?14:18),Glass.dp(c,compact?8:12));views.setTextViewTextSize(R.id.widget_balance,android.util.TypedValue.COMPLEX_UNIT_SP,compact?26:32);
  views.setOnClickPendingIntent(R.id.widget_title,activity(c,id,""));views.setOnClickPendingIntent(R.id.widget_balance,activity(c,id,""));views.setOnClickPendingIntent(R.id.widget_expense_action,activity(c,id,"expense"));views.setOnClickPendingIntent(R.id.widget_income_action,activity(c,id,"income"));views.setOnClickPendingIntent(R.id.widget_move_action,activity(c,id,"transfer"));views.setOnClickPendingIntent(R.id.widget_settings,configure(c,id));views.setOnClickPendingIntent(R.id.widget_refresh,PendingIntent.getBroadcast(c,id,new Intent(c,BolsilloWidget.class).setAction(REFRESH).setData(identity(id,"refresh")).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
  try{Snapshot snapshot=snapshot(c,options);if(snapshot.missing)views.setViewVisibility(R.id.widget_actions,View.GONE);views.setTextViewText(R.id.widget_label,snapshot.label);views.setTextViewText(R.id.widget_balance,snapshot.missing?"—":hidden?"••••••":money(snapshot.value));boolean total=options.optString("display","total").equals("total");views.setTextViewText(R.id.widget_left_label,total?"Disponible":"Ingresos del mes");views.setTextViewText(R.id.widget_right_label,total?"Ahorro":"Gastos del mes");views.setTextViewText(R.id.widget_left_value,hidden?"••••":snapshot.missing?"—":money(total?snapshot.available:snapshot.income));views.setTextViewText(R.id.widget_right_value,hidden?"••••":snapshot.missing?"—":money(total?snapshot.savings:snapshot.expense));long first=total?Math.max(0,snapshot.available):snapshot.income,second=total?Math.max(0,snapshot.savings):snapshot.expense;views.setViewVisibility(R.id.widget_flow,!compact&&!hidden&&!snapshot.missing&&first+second>0?View.VISIBLE:View.GONE);views.setImageViewBitmap(R.id.widget_flow,flow(skin,first,second));views.setTextViewText(R.id.widget_detail,hidden?"Importes privados · saldo local":snapshot.detail);String timestamp=snapshot.updated==0?"Sin actualizar":"Actualizado "+android.text.format.DateFormat.format("dd/MM HH:mm",snapshot.updated);views.setTextViewText(R.id.widget_updated,timestamp+(snapshot.queued>0?" · "+snapshot.queued+" locales":""));}
  catch(Exception error){views.setViewVisibility(R.id.widget_stats,View.GONE);views.setViewVisibility(R.id.widget_flow,View.GONE);views.setTextViewText(R.id.widget_label,"Tus saldos, aquí");views.setTextViewText(R.id.widget_balance,"Abre Bolsillo");views.setTextViewText(R.id.widget_detail,"Prepara tus cuentas en la app");views.setTextViewText(R.id.widget_updated,"Guardado local");}
  return views;
 }
}
